import{_ as t,o,c as u,ag as q}from"./chunks/framework.DaAXJYxM.js";const i=JSON.parse('{"title":"第112章 第二个工作表","description":"","frontmatter":{},"headers":[],"relativePath":"第112章_第二个工作表.md","filePath":"第112章_第二个工作表.md"}'),e={name:"第112章_第二个工作表.md"};function _(a,p,r,s,n,l){return o(),u("div",null,[...p[0]||(p[0]=[q('<h1 id="第112章-第二个工作表" tabindex="-1">第112章 第二个工作表 <a class="header-anchor" href="#第112章-第二个工作表" aria-label="Permalink to &quot;第112章 第二个工作表&quot;">​</a></h1><p>那年一月末，她发给我一份表格。</p><p>我把它归档在&quot;行政&quot;那个文件夹里。</p><p>我说的是真的&quot;行政&quot;。</p><p>我这几年在电脑上分了六个大文件夹：合同、发票、货、行政、别的、家里。</p><p>她这一份，我那天随手丢进&quot;行政&quot;。</p><p>因为它是随一月的结算一起过来的。</p><p>那封邮件的正文只有一行。</p><p>她说：附件一是账，附件二是我让你记的，你别丢。</p><p>我说：好。</p><p>那一次她只写了六个字：账我核过了，没问题。</p><p>我把这两个附件下载下来。</p><p>我打开了第一个。</p><p>第二个我没开。</p><p>第二个我在电脑里存了十一个月。</p><p>十一个月以后，就是今年冬天，我在整理那 41 个 G 的时候，我把&quot;行政&quot;那个文件夹点开。</p><p>里面有 63 个文件。</p><p>我一个一个往下拉。</p><p>我看到一个 8 KB 的 xlsx。</p><p>文件名是四个字：附件二.xlsx。</p><p>我那时候已经不记得这是什么了。</p><p>我双击打开。</p><p>里面有三个工作表。</p><p>第一张叫&quot;账&quot;。</p><p>第二张叫&quot;你要记的&quot;。</p><p>第三张叫&quot;如果你不想记&quot;。</p><p>我先看第二张。</p><p>她那张表做得很丑。</p><p>她没有调行高，字全部挤在上面。</p><p>第一列是事情，第二列是时间，第三列是空的。</p><p>第三列她标了个题，写的是&quot;我做过了&quot;。</p><p>那第三列一格也没填。</p><p>第二张表里的东西我抄下来：</p><p>一，你那个腰，冬天早上起来先在床上坐一分钟再站起来。医院那个医生讲的，你从来不听。</p><p>二，那个仓库里防潮的包，一年换两次，四月和十月。我这边买不到，你自己查。</p><p>三，我的那个画册，别放在窗底下，那个纸晒了就黄。</p><p>四，绿萝（我这盆在你那儿，你要浇水，四天一次，一次半杯）。</p><p>五，我妈生日三月十七。你不要跟我讲你记得，你别提，她不喜欢人家记得。</p><p>六，我妹九月四号开学，她要一个发卡，粉的那种，你别买贵。</p><p>七，我这边冬天你那边如果下雪，你穿那双新的，别穿那双旧的，旧的那个底滑。</p><p>八，我如果不上了，你把这个表继续填。</p><p>第九条她写得跟前面不一样。</p><p>前面八条她是一行一条。</p><p>第九条她写了四行。</p><p>第九条是：</p><p>&quot;这一条你可以不看。&quot;</p><p>&quot;这一条是：如果有一天我不讲话了，你不要来问我为什么。&quot;</p><p>&quot;你不要来问，因为我要是答，我要撒一个很大的谎。&quot;</p><p>&quot;你要是不问我，我这个谎就不用撒。你可以当我忙。&quot;</p><p>我把这一条读了三遍。</p><p>然后我点开第三张工作表。</p><p>第三张表只有一行。</p><p>那一行写的是：</p><p>&quot;如果你不想记，你就把这个表删了。我不在意。&quot;</p><p>我坐在那儿，我把电脑关掉。</p><p>我把电脑关掉以后我又打开。</p><p>我又把那三张表读了一遍。</p><p>读到第二遍的时候，我注意到一件事。</p><p>第一张&quot;账&quot;那一页，最下面还有一行，不在表格里，写在表格外面的第 214 行。</p><p>那一行没有格子，字很小。</p><p>写的是：</p><p>&quot;这次的钱我算过两遍。第二遍多算了十九块，我把它留着了，你别管。&quot;</p><p>我看到这十九块，我一下子想到那年二月那个立牌。</p><p>那个二十四块的立牌，她说她全出，因为她那天晚上不想让我替她想。</p><p>我把那两个数并在一起看。</p><p>十九，二十四。</p><p>我那天晚上把那三张表打印出来。</p><p>我打印出来是因为我要拿一张纸。</p><p>我在&quot;如果你不想记，你就把这个表删了。我不在意。&quot;这一行下面，用笔划了一道。</p><p>划完我在旁边写了一个字。</p><p>我写的是&quot;记&quot;。</p><p>那天夜里我给她发了一句。</p><p>我说，你一月发给我的那个表，附件二，我今年才打开。</p><p>她隔了很久。</p><p>她那天是她那边上午。</p><p>她回的是：我知道。</p><p>我说，你怎么知道。</p><p>她说，因为你今天才讲。</p><p>她说，你要是早就看了，你不会到今天才讲。</p><p>她说，我那天发出去以后我等了你三天。</p><p>她说，你三天里跟我讲了十一次货的事，你没提那个表。</p><p>她说，我就当你没开。</p><p>我说，我今天开了。</p><p>她说，嗯。</p><p>我说，我看了三张。</p><p>她说，嗯。</p><p>我说，第三张那句&quot;我不在意&quot;，你写的时候在不在意。</p><p>她很久没回。</p><p>久到我以为她去上课了。</p><p>然后她回了一段。</p><p>这一段是我今年读到的最长的一段她讲她自己为什么讲话。</p><p>她说，我这个人在手机上写不出来那种话。</p><p>她说，我写&quot;你不要来问我&quot;我能写，因为这是一件事。</p><p>她说，我写&quot;我想你&quot;我写不出来，因为那不是一件事，那是一个我要负责的东西。</p><p>她说，所以我把所有想讲的话全部改成&quot;你要做什么&quot;。</p><p>她说，我改得很熟练。</p><p>她说，我十四岁那年就开始了。</p><p>她说，我妈那时候每天讲一遍她这一辈子都给你了。</p><p>她说，我从那年起我不会讲我要什么，我只讲我该干什么。</p><p>她说，我这张表上九条，八条是让你干什么。</p><p>她说，第九条是我不让你干什么。</p><p>她说，我把第九条写四行是因为我这一辈子只在这条上讲了一句真话。</p><p>她说，我这一辈子讲真话只能讲&quot;你别问我&quot;。</p><p>她说，因为我一问三不应，我就得承认我不来了。</p><p>她说，我承认我不来了，我就要承认我这一年排的四个版本全部白排。</p><p>她说，我白排了我就得跟我妈讲这四千七是干什么用的。</p><p>她说，我讲不出来。</p><p>她说，所以那张表最后我加了一行&quot;如果你不想记&quot;。</p><p>她说，那一行是我为我自己留的。</p><p>她说，我留了那一条，我就不是我求你。</p><p>她说，我不求你这个人，我这辈子做不到。</p><p>我那天夜里没有回她。</p><p>我坐在电脑前面。</p><p>我把那张纸从打印机上取下来，我把那个 8 KB 的 xlsx 从&quot;行政&quot;那个文件夹里移出来。</p><p>我移到哪里，我想了很久。</p><p>我最后把它放进那个没有名字的子文件夹。</p><p>那个文件夹原来是 3.4 个 G。</p><p>放进去以后，它多了 8 KB。</p><p>那天夜里我在本子的第一页重新写了一句话。</p><p>我写：我这十一年把她说过的所有话存在 41 个 G 里，我以为这叫记得。</p><p>我写：她那年一月给我的是一份表格。</p><p>我写：她把告别拆成了交代，因为她讲不出再见，她只会讲你要做什么。</p><p>我写：而我十一个月没打开。</p>',123)])])}const d=t(e,[["render",_]]);export{i as __pageData,d as default};
